using System;using System.IO;using System.Linq;using UnityEngine;using Racer;using Object=UnityEngine.Object;
public static class InspectCleanupFaces {public static string Main(){var road=Object.FindAnyObjectByType<RaceDirector>().road;var go=new GameObject("Temp rays",typeof(Camera));var c=go.GetComponent<Camera>();c.fieldOfView=70;c.aspect=1100f/720;var p=road.At(1566.734f,out var f);c.transform.SetPositionAndRotation(p+Vector3.up*4-f*7,Quaternion.LookRotation(f*22-Vector3.up*2));var old=Physics.queriesHitBackfaces;Physics.queriesHitBackfaces=true;var report="";foreach(var xy in new[]{new Vector2(.5f,.60f),new(.55f,.60f),new(.58f,.59f),new(.55f,.55f),new(.6f,.6f),new(.5f,.55f)}){var hits=Physics.RaycastAll(c.ViewportPointToRay(xy),300,1,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance).Take(4);report+=xy+" "+string.Join(";",hits.Select(h=>h.collider.name+" "+h.point.ToString("F1")+" triangle="+h.triangleIndex))+"\n";}Physics.queriesHitBackfaces=old;Object.DestroyImmediate(go);return report;}}


